autoBackup: async () => {
    if (isBackupDB) return;

    let meta = await DB.get(BACKUP_META_KEY);
    if (!meta) meta = { lastSavedYMD: '', savedDbKeys: [] };

    const now = new Date();
    const yesterday = new Date(now);
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayYMD = formatYMD(yesterday);

    // lastSavedYMD 가 어제보다 작으면 백업 수행
    if (meta.lastSavedYMD < yesterdayYMD) {
        const backupDbName = `213-${yesterdayYMD}`;

        // 기존 백업이 있으면 삭제 후 새로 복사
        await DB.deleteDatabase(backupDbName);
        await DB.copyAllTo(backupDbName);

        // 메타 업데이트
        meta.lastSavedYMD = yesterdayYMD;
        if (!meta.savedDbKeys.includes(yesterdayYMD)) {
            meta.savedDbKeys.push(yesterdayYMD);
            meta.savedDbKeys.sort();
        }

        // 7 일보다 오래된 백업 삭제
        const cutoff = new Date(now);
        cutoff.setDate(cutoff.getDate() - 7);
        const cutoffYMD = formatYMD(cutoff);

        const oldKeys = meta.savedDbKeys.filter(k => k < cutoffYMD);
        for (const k of oldKeys) {
            await DB.deleteDatabase(`213-${k}`);
        }
        meta.savedDbKeys = meta.savedDbKeys.filter(k => k >= cutoffYMD);

        await DB.save(BACKUP_META_KEY, meta);
    }
